blobs={}
with tarfile.open(fileobj=io.BytesIO(archive),mode='r:gz') as tf:
 for item in tf.getmembers():
  assert item.isfile() and item.name in entries
  data=tf.extractfile(item).read(); expected=entries[item.name]
  assert len(data)==expected['size'] and hashlib.sha256(data).hexdigest()==expected['sha256']
  dest=ROOT/item.name;assert dest.resolve().is_relative_to(ROOT)
  if dest.exists():assert dest.is_file() and hashlib.sha256(dest.read_bytes()).hexdigest()==expected['sha256'],'Existing file differs: '+str(dest)
  blobs[item.name]=data
assert set(blobs)==set(entries)
added=[];verified=[]
for name,data in blobs.items():
 dest=ROOT/name
 if not dest.exists():
  dest.parent.mkdir(parents=True,exist_ok=True)
  fd,temp=tempfile.mkstemp(prefix='.instance-repair-',dir=dest.parent)
  try:
   with os.fdopen(fd,'wb') as f:f.write(data)
   os.chmod(temp,0o644)
   try:os.link(temp,dest);added.append(entries[name]['instance'])
   except FileExistsError:pass
  finally:os.unlink(temp)
 assert hashlib.sha256(dest.read_bytes()).hexdigest()==entries[name]['sha256']
 verified.append(entries[name]['instance'])
print('B1KPROBE_BEGIN'+base64.b64encode(json.dumps({'root':str(ROOT),'added':added,'verified':verified,'bytes':sum(len(x) for x in blobs.values()),'complete':len(verified)==20}).encode()).decode()+'B1KPROBE_END',flush=True)
